class Binding:
    def __init__(self, name, type, token, skip=False):
        self.name = name
        self.type = type # 'let', 'lambda-arg', 'lambda-pattern'
        self.token = token
        self.skip = skip
        self.used = False
        self.refs = set() # Bindings this binding refers to
        self.id = id(self)

class Scope:
    def __init__(self, parent=None):
        self.parent = parent
        self.bindings = {} # name -> Binding

