    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
        self.all_bindings = []
        self.current_scope = Scope()

    def peek(self, n=0):
        return self.tokens[self.pos + n] if self.pos + n < len(self.tokens) else None
    def consume(self):
        t = self.peek()
        self.pos += 1
        return t

    def parse(self):
        self.expr()
        return self.all_bindings

    def expr(self):
        t = self.peek()
        if not t: return
        if t.type == 'KEYWORD' and t.value == 'let':
            self.consume()
            old_scope = self.current_scope
            new_scope = Scope(old_scope)
            self.current_scope = new_scope

            # We need to collect all bindings in this let first because they are mutually recursive
            bindings_in_this_let = []
            while self.peek() and not (self.peek().type == 'KEYWORD' and self.peek().value == 'in'):
                b = self.binding()
                if b:
                    if isinstance(b, list):
                        bindings_in_this_let.extend(b)
                    else:
                        bindings_in_this_let.append(b)
                else:
                    self.consume() # Skip unknown tokens

            for b in bindings_in_this_let:
                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)

            if self.peek() and self.peek().value == 'in':
                self.consume()
                self.expr()

            self.current_scope = old_scope
        elif t.type == 'KEYWORD' and t.value == 'rec':
            self.consume()
            if self.peek() and self.peek().value == '{':
                self.attrset(is_rec=True)
        elif t.type == 'SYMBOL' and t.value == '{':
            # Could be lambda or attrset
            if self.is_lambda():
                self.lambda_expr()
            else:
                self.attrset()
        elif t.type == 'ID':
            if self.is_lambda():
                self.lambda_expr()
            else:
                self.record_usage(self.consume())
        elif t.type == 'SYMBOL' and t.value == '(':
            self.consume()
            self.expr()
            if self.peek() and self.peek().value == ')':
                self.consume()
        else:
            self.consume()

    def is_lambda(self):
        p = self.pos
        if self.tokens[p].type == 'ID':
            p += 1
            if p < len(self.tokens) and self.tokens[p].type == 'SYMBOL' and self.tokens[p].value == ':':
                return True
            if p < len(self.tokens) and self.tokens[p].type == 'SYMBOL' and self.tokens[p].value == '@':
                return True
        elif self.tokens[p].type == 'SYMBOL' and self.tokens[p].value == '{':
            # Skip until matching }
            depth = 0
            while p < len(self.tokens):
                if self.tokens[p].type == 'SYMBOL' and self.tokens[p].value == '{':
                    depth += 1
                elif self.tokens[p].type == 'SYMBOL' and self.tokens[p].value == '}':
                    depth -= 1
                    if depth == 0:
                        p += 1
                        if p < len(self.tokens) and (self.tokens[p].type == 'SYMBOL' and (self.tokens[p].value == ':' or self.tokens[p].value == '@')):
                            return True
                        return False
                p += 1
        return False

    def lambda_expr(self):
        old_scope = self.current_scope
        new_scope = Scope(old_scope)
        self.current_scope = new_scope

