                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)
                self.pattern(new_scope)
            else:
                # arg : expr
                b = Binding(arg.value, 'lambda-arg', arg)
                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)
        elif t.type == 'SYMBOL' and t.value == '{':
            self.pattern(new_scope)
            if self.peek() and self.peek().value == '@':
                self.consume()
                if self.peek() and self.peek().type == 'ID':
                    arg = self.consume()
                    b = Binding(arg.value, 'lambda-arg', arg)
                    new_scope.bindings[b.name] = b
                    self.all_bindings.append(b)

        if self.peek() and self.peek().value == ':':
            self.consume()
            self.expr()

        self.current_scope = old_scope

    def pattern(self, scope):
        self.consume() # {
        while self.peek() and not (self.peek().type == 'SYMBOL' and self.peek().value == '}'):
            t = self.peek()
            if t.type == 'ID':
                name_token = self.consume()
                b = Binding(name_token.value, 'lambda-pattern', name_token)
                scope.bindings[b.name] = b
                self.all_bindings.append(b)
                if self.peek() and self.peek().value == '?':
                    self.consume()
                    self.expr() # Default value
            elif t.type == 'SYMBOL' and t.value == '...':
                self.consume()
            elif t.type == 'SYMBOL' and t.value == ',':
                self.consume()
            else:
                break
        if self.peek() and self.peek().value == '}':
            self.consume()

    def binding(self):
        t = self.peek()
        if not t: return None

        # Check for skip pragma
        skip = False
        i = self.pos - 1
        while i >= 0:
            prev = self.tokens[i]
            if prev.type == 'COMMENT':
                if 'deadnix: skip' in prev.value:
                    if prev.line == t.line - 1:
                        skip = True
                break
            if prev.line < t.line - 1:
                break
            i -= 1

        if t.type == 'KEYWORD' and t.value == 'inherit':
            self.consume()
            source_expr = None
            if self.peek() and self.peek().value == '(':
                self.consume()
                source_expr = True
                self.expr() # The source expression
                if self.peek() and self.peek().value == ')':
                    self.consume()

            inherited_bindings = []
            while self.peek() and self.peek().type == 'ID':
                id_token = self.consume()
                b = Binding(id_token.value, 'let', id_token, skip=skip)
                inherited_bindings.append(b)
            if self.peek() and self.peek().value == ';':
                self.consume()
            return inherited_bindings

        if t.type == 'ID':
            name_token = self.consume()
            # Handle dotted
            while self.peek() and self.peek().value == '.':
                self.consume()
                self.expr() # Consume the part after dot
            if self.peek() and self.peek().value == '=':
                self.consume()
                b = Binding(name_token.value, 'let', name_token, skip=skip)
                self.expr()
                if self.peek() and self.peek().value == ';':
                    self.consume()
                return b
        return None

    def attrset(self, is_rec=False):
        self.consume() # {
        old_scope = self.current_scope
        if is_rec:
            new_scope = Scope(old_scope)
            self.current_scope = new_scope
            # Pre-collect bindings if needed

        while self.peek() and not (self.peek().type == 'SYMBOL' and self.peek().value == '}'):
            self.binding() # In attrsets, bindings don't count for deadnix unused let bindings

        if self.peek() and self.peek().value == '}':
            self.consume()
        self.current_scope = old_scope

    def record_usage(self, t):
        name = t.value
        s = self.current_scope
        while s:
            if name in s.bindings:
                s.bindings[name].used = True
                return
            s = s.parent

