                    if self.code.startswith('${', self.pos):
                        tokens.append(Token('SYMBOL', '${', self.line, self.col, self.col + 2))
                        self.pos += 2
                        self.col += 2
                        continue
                    if self.code[self.pos] == '\n':
                        self.line += 1
                        self.col = 1
                    else:
                        self.col += 1
                    self.pos += 1
                if self.pos < len(self.code) and self.code.startswith("''", self.pos):
                    tokens.append(Token('SYMBOL', "''", self.line, self.col, self.col + 2))
                    self.pos += 2
                    self.col += 2
                continue
            found = False
            for s in ['...', '==', '!=', '&&', '||', '->', '//', '++']:
                if self.code.startswith(s, self.pos):
                    tokens.append(Token('SYMBOL', s, self.line, self.col, self.col + len(s)))
                    self.pos += len(s)
                    self.col += len(s)
                    found = True
                    break
            if found: continue
            if self.code.startswith('${', self.pos):
                tokens.append(Token('SYMBOL', '${', self.line, self.col, self.col + 2))
                self.pos += 2
                self.col += 2
                continue
            for s in '{}(),;:=@.?:+-*/!<>[]':
                if c == s:
                    tokens.append(Token('SYMBOL', s, self.line, self.col, self.col + 1))
                    self.pos += 1
                    self.col += 1
                    found = True
                    break
            if found: continue
            if c.isdigit():
                start_line, start_col = self.line, self.col
                val = ""
                while self.pos < len(self.code) and (self.code[self.pos].isdigit() or self.code[self.pos] == '.'):
                    val += self.code[self.pos]
                    self.pos += 1
                    self.col += 1
                tokens.append(Token('NUMBER', val, start_line, start_col, self.col))
                continue
            self.pos += 1
            self.col += 1
        return tokens

class Binding:
    def __init__(self, name, type, token, skip=False):
        self.name = name
        self.type = type # 'let', 'lambda-arg', 'lambda-pattern'
        self.token = token
        self.skip = skip
        self.reachable = False
        self.refs = set() # Set of Binding objects it references
        self.range_start = 0 # Byte offset for removal
        self.range_end = 0

class Scope:
    def __init__(self, parent=None):
        self.parent = parent
        self.bindings = {} # name -> Binding

class Parser:
    def __init__(self, tokens, code, options):
        self.tokens = tokens
        self.code = code
        self.options = options
        self.pos = 0
        self.all_bindings = []
        self.current_scope = Scope()
        self.token_offsets = []
        self._build_token_offsets()

    def _build_token_offsets(self):
        # Build line/col to byte offset map
        line_offsets = [0]
        for i, c in enumerate(self.code):
            if c == '\n':
                line_offsets.append(i + 1)
        self.line_offsets = line_offsets

    def get_offset(self, line, col):
        return self.line_offsets[line - 1] + col - 1

    def peek(self, n=0):
        return self.tokens[self.pos + n] if self.pos + n < len(self.tokens) else None
    def consume(self):
        t = self.peek()
        self.pos += 1
        return t

    def parse(self):
        self.expr(is_root=True)
        self._analyze_reachability()
        return self.all_bindings

    def _analyze_reachability(self):
        changed = True
        while changed:
            changed = False
            for b in self.all_bindings:
                if b.reachable:
                    for ref in b.refs:
                        if not ref.reachable:
                            ref.reachable = True
                            changed = True

    def expr(self, is_root=False):
        t = self.peek()
        if not t: return
        if t.type == 'KEYWORD' and t.value == 'let':
            self.consume()
            old_scope = self.current_scope
            new_scope = Scope(old_scope)
            self.current_scope = new_scope

            bindings_in_this_let = []
            while self.peek() and not (self.peek().type == 'KEYWORD' and self.peek().value == 'in'):
                start_pos = self.pos
                b = self.binding()
                if b:
                    if isinstance(b, list):
                        for bb in b:
                            bb.range_start = self.get_offset(self.tokens[start_pos].line, self.tokens[start_pos].col)
                            # range_end will be set at the end of binding()
                            bindings_in_this_let.append(bb)
                    else:
                        b.range_start = self.get_offset(self.tokens[start_pos].line, self.tokens[start_pos].col)
                        bindings_in_this_let.append(b)
                else:
                    self.consume()

            for b in bindings_in_this_let:
                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)

            if self.peek() and self.peek().value == 'in':
                self.consume()
                self.expr(is_root=is_root) # Body of let is root if let is root

            self.current_scope = old_scope
        elif t.type == 'SYMBOL' and t.value == '{':
            if self.is_lambda():
                self.lambda_expr(is_root=is_root)
            else:
                self.attrset()
        elif t.type == 'ID':
            if self.is_lambda():
                self.lambda_expr(is_root=is_root)
            else:
                self.record_usage(self.consume(), is_root)
        elif t.type == 'SYMBOL' and t.value == '(':
            self.consume()
            self.expr(is_root=is_root)
            if self.peek() and self.peek().value == ')':
                self.consume()
        else:
            self.consume()

    def is_lambda(self):
        p = self.pos
        if self.tokens[p].type == 'ID':
            p += 1
            if p < len(self.tokens) and self.tokens[p].value in (':', '@'): return True
        elif self.tokens[p].value == '{':
            depth = 0
            while p < len(self.tokens):
                if self.tokens[p].value == '{': depth += 1
                elif self.tokens[p].value == '}':
                    depth -= 1
                    if depth == 0:
                        p += 1
                        if p < len(self.tokens) and self.tokens[p].value in (':', '@'): return True
                        return False
                p += 1
        return False

    def lambda_expr(self, is_root=False):
        old_scope = self.current_scope
        new_scope = Scope(old_scope)
        self.current_scope = new_scope

        t = self.peek()
        if t.type == 'ID':
            arg = self.consume()
            if self.peek() and self.peek().value == '@':
                self.consume()
                b = Binding(arg.value, 'lambda-arg', arg)
                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)
                self.pattern(new_scope)
            else:
                b = Binding(arg.value, 'lambda-arg', arg)
                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)
        elif t.type == 'SYMBOL' and t.value == '{':
            self.pattern(new_scope)
            if self.peek() and self.peek().value == '@':
                self.consume()
                if self.peek() and self.peek().type == 'ID':
                    arg = self.consume()
                    b = Binding(arg.value, 'lambda-arg', arg)
                    new_scope.bindings[b.name] = b
                    self.all_bindings.append(b)

        if self.peek() and self.peek().value == ':':
            self.consume()
            self.expr(is_root=is_root)
        self.current_scope = old_scope

    def pattern(self, scope):
        self.consume() # {
        while self.peek() and not (self.peek().value == '}'):
            t = self.peek()
            if t.type == 'ID':
                name_token = self.consume()
                b = Binding(name_token.value, 'lambda-pattern', name_token)
                scope.bindings[b.name] = b
                self.all_bindings.append(b)
                if self.peek() and self.peek().value == '?':
                    self.consume()
                    self.expr(is_root=False) # Default value
            elif t.type == 'SYMBOL' and t.value in ('...', ','): self.consume()
            else: break
        if self.peek() and self.peek().value == '}': self.consume()

    def binding(self):
        t = self.peek()
        if not t: return None
        skip = False
        i = self.pos - 1
        while i >= 0:
            if self.tokens[i].type == 'COMMENT' and 'deadnix: skip' in self.tokens[i].value:
                if self.tokens[i].line == t.line - 1: skip = True
                break
            if self.tokens[i].line < t.line - 1: break
            i -= 1

        if t.type == 'KEYWORD' and t.value == 'inherit':
            self.consume()
            if self.peek() and self.peek().value == '(':
                self.consume()
                self.expr(is_root=False)
                if self.peek() and self.peek().value == ')': self.consume()

            inherited_bindings = []
            while self.peek() and self.peek().type == 'ID':
                id_token = self.consume()
                b = Binding(id_token.value, 'let', id_token, skip=skip)
                inherited_bindings.append(b)
            if self.peek() and self.peek().value == ';':
                end_token = self.consume()
                end_off = self.get_offset(end_token.line, end_token.end_col)
                for b in inherited_bindings: b.range_end = end_off
            return inherited_bindings

        if t.type == 'ID':
            name_token = self.consume()
            while self.peek() and self.peek().value == '.':
                self.consume()
                if self.peek() and self.peek().type == 'ID': self.consume()
            if self.peek() and self.peek().value == '=':
                self.consume()
                b = Binding(name_token.value, 'let', name_token, skip=skip)
                # To collect refs in RHS, we need to temporarily set the "current binding"
                self.current_binding = b
                self.expr(is_root=False)
                self.current_binding = None
                if self.peek() and self.peek().value == ';':
                    end_token = self.consume()
                    b.range_end = self.get_offset(end_token.line, end_token.end_col)
                return b
        return None

    def attrset(self):
        self.consume() # {
        while self.peek() and not (self.peek().value == '}'):
            self.binding() or self.consume()
        if self.peek() and self.peek().value == '}': self.consume()

    def record_usage(self, t, is_root):
        name = t.value
        s = self.current_scope
        while s:
            if name in s.bindings:
                b = s.bindings[name]
                if is_root: b.reachable = True
                if hasattr(self, 'current_binding') and self.current_binding:
                    self.current_binding.refs.add(b)
                return
            s = s.parent

def run_on_file(filepath, options):
    try:
        with open(filepath, 'r') as f:
            code = f.read()
    except Exception as e:
        return []

    lexer = Lexer(code)
    tokens = lexer.tokenize()
    parser = Parser(tokens, code, options)
    all_bindings = parser.parse()

    results = []
    for b in all_bindings:
        if b.skip: continue
        if b.name.startswith('_') and options.no_underscore: continue
        if b.type == 'lambda-arg' and options.no_lambda_arg: continue
        if b.type == 'lambda-pattern' and options.no_lambda_pattern: continue

        if not b.reachable:
            msg = f"Unused {b.type.replace('-', ' ')}: {b.name}"
            results.append({
                'file': filepath,
                'line': b.token.line,
                'column': b.token.col,
                'endColumn': b.token.end_col,
                'message': msg,
                'range_start': b.range_start,
                'range_end': b.range_end
            })

    if options.edit and results:
        new_code = list(code)
        # Sort results by range_start descending to avoid offset issues
        for res in sorted(results, key=lambda x: x['range_start'], reverse=True):
            if res['range_start'] < res['range_end']:
                # Also try to remove preceding whitespace and following newline
                start = res['range_start']
                end = res['range_end']

                # Check if it's the only thing on the line
                # This is a bit simplified
                while start > 0 and code[start-1] in ' \t': start -= 1
                if end < len(code) and code[end] == '\n': end += 1

                new_code[start:end] = []
        with open(filepath, 'w') as f:
            f.write("".join(new_code))

    return results

def main():
    parser = argparse.ArgumentParser(description='Find dead code in .nix files')
    parser.add_argument('file_paths', nargs='*', default=['.'])
    parser.add_argument('-l', '--no-lambda-arg', action='store_true')
    parser.add_argument('-L', '--no-lambda-pattern-names', action='store_true', dest='no_lambda_pattern')
    parser.add_argument('-_', '--no-underscore', action='store_true')
    parser.add_argument('-q', '--quiet', action='store_true')
    parser.add_argument('-e', '--edit', action='store_true')
    parser.add_argument('-h', '--hidden', action='store_true')
    parser.add_argument('-f', '--fail', action='store_true')
    parser.add_argument('-o', '--output-format', default='human-readable')
    parser.add_argument('--exclude', nargs='*', default=[])
    parser.add_argument('-V', '--version', action='store_true')

    args = parser.parse_args()
    if args.version:
        print("deadnix 1.3.1")
        return

    all_results = []
    files_to_process = []

    def add_files(path):
        if os.path.isfile(path):
            if path.endswith('.nix'): files_to_process.append(path)
        elif os.path.isdir(path):
            for root, dirs, files in os.walk(path):
                if not args.hidden:
                    dirs[:] = [d for d in dirs if not d.startswith('.')]
                for f in files:
                    if f.endswith('.nix'):
                        if not args.hidden and f.startswith('.'): continue
                        p = os.path.join(root, f)
                        files_to_process.append(p)

    for p in args.file_paths:
        add_files(p)

    # Filter excludes
    exclude_paths = [os.path.abspath(p) for p in args.exclude]
    files_to_process = [f for f in files_to_process if os.path.abspath(f) not in exclude_paths]
    # Also handle directory excludes
    files_to_process = [f for f in files_to_process if not any(os.path.abspath(f).startswith(e + os.sep) for e in exclude_paths)]

    for f in files_to_process:
        all_results.extend(run_on_file(f, args))

    if args.output_format == 'json':
        # Group by file
        grouped = {}
        for res in all_results:
            f = res['file']
            if f not in grouped: grouped[f] = {'file': f, 'results': []}
            grouped[f]['results'].append({
                'column': res['column'],
                'endColumn': res['endColumn'],
                'line': res['line'],
                'message': res['message']
            })
        for f in sorted(grouped.keys()):
            print(json.dumps(grouped[f]))
    else:
        if not args.quiet:
            for res in all_results:
                print(f"{YELLOW}Warning:{RESET} Unused declarations were found.")
                print(f"    {GRAY}╭─{RESET}{GRAY}[{RESET}{res['file']}:{res['line']}:{res['column']}{GRAY}]{RESET}")
                # Print code line
                with open(res['file'], 'r') as f:
                    lines = f.readlines()
                    line_content = lines[res['line']-1].rstrip('\n')
                    print(f" {GRAY}{res['line']} │{RESET} {LIGHT_GRAY}{line_content}{RESET}")
                    # Print pointer
                    padding = " " * (res['column'] - 1)
                    # This part is complex to match exactly, but let's try
                    pointer = " " * (res['column'] - 1) + RED + "╰" + "─" * (res['endColumn'] - res['column'] - 1) + " " + res['message'] + RESET
                    print(f" {DARK_GRAY}   │{RESET}     {pointer}")

    if args.fail and all_results:
        sys.exit(1)

if __name__ == '__main__':
    main()
