                        bindings_in_this_let.append(b)
                else:
                    self.consume()

            for b in bindings_in_this_let:
                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)

            if self.peek() and self.peek().value == 'in':
                self.consume()
                self.expr(is_root=is_root) # Body of let is root if let is root

            self.current_scope = old_scope
        elif t.type == 'SYMBOL' and t.value == '{':
            if self.is_lambda():
                self.lambda_expr(is_root=is_root)
            else:
                self.attrset()
        elif t.type == 'ID':
            if self.is_lambda():
                self.lambda_expr(is_root=is_root)
            else:
                self.record_usage(self.consume(), is_root)
        elif t.type == 'SYMBOL' and t.value == '(':
            self.consume()
            self.expr(is_root=is_root)
            if self.peek() and self.peek().value == ')':
                self.consume()
        else:
            self.consume()

    def is_lambda(self):
        p = self.pos
        if self.tokens[p].type == 'ID':
            p += 1
            if p < len(self.tokens) and self.tokens[p].value in (':', '@'): return True
        elif self.tokens[p].value == '{':
            depth = 0
            while p < len(self.tokens):
                if self.tokens[p].value == '{': depth += 1
                elif self.tokens[p].value == '}':
                    depth -= 1
                    if depth == 0:
                        p += 1
                        if p < len(self.tokens) and self.tokens[p].value in (':', '@'): return True
                        return False
                p += 1
        return False

    def lambda_expr(self, is_root=False):
        old_scope = self.current_scope
        new_scope = Scope(old_scope)
        self.current_scope = new_scope

        t = self.peek()
        if t.type == 'ID':
            arg = self.consume()
            if self.peek() and self.peek().value == '@':
                self.consume()
                b = Binding(arg.value, 'lambda-arg', arg)
                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)
                self.pattern(new_scope)
            else:
                b = Binding(arg.value, 'lambda-arg', arg)
                new_scope.bindings[b.name] = b
                self.all_bindings.append(b)
        elif t.type == 'SYMBOL' and t.value == '{':
            self.pattern(new_scope)
            if self.peek() and self.peek().value == '@':
                self.consume()
                if self.peek() and self.peek().type == 'ID':
                    arg = self.consume()
                    b = Binding(arg.value, 'lambda-arg', arg)
                    new_scope.bindings[b.name] = b
                    self.all_bindings.append(b)

