        i = self.pos - 1
        while i >= 0:
            if self.tokens[i].type == 'COMMENT' and 'deadnix: skip' in self.tokens[i].value:
                if self.tokens[i].line == t.line - 1: skip = True
                break
            if self.tokens[i].line < t.line - 1: break
            i -= 1

        if t.type == 'KEYWORD' and t.value == 'inherit':
            self.consume()
            if self.peek() and self.peek().value == '(':
                self.consume()
                self.expr(is_root=False)
                if self.peek() and self.peek().value == ')': self.consume()

            inherited_bindings = []
            while self.peek() and self.peek().type == 'ID':
                id_token = self.consume()
                b = Binding(id_token.value, 'let', id_token, skip=skip)
                inherited_bindings.append(b)
            if self.peek() and self.peek().value == ';':
                end_token = self.consume()
                end_off = self.get_offset(end_token.line, end_token.end_col)
                for b in inherited_bindings: b.range_end = end_off
