    def record_usage(self, t, is_root):
        name = t.value
        s = self.current_scope
        while s:
            if name in s.bindings:
                b = s.bindings[name]
                if is_root: b.reachable = True
                if hasattr(self, 'current_binding') and self.current_binding:
                    self.current_binding.refs.add(b)
                return
            s = s.parent

def run_on_file(filepath, options):
    try:
        with open(filepath, 'r') as f:
            code = f.read()
    except Exception as e:
        return []

    lexer = Lexer(code)
    tokens = lexer.tokenize()
    parser = Parser(tokens, code, options)
    all_bindings = parser.parse()

    results = []
    for b in all_bindings:
        if b.skip: continue
        if b.name.startswith('_') and options.no_underscore: continue
        if b.type == 'lambda-arg' and options.no_lambda_arg: continue
        if b.type == 'lambda-pattern' and options.no_lambda_pattern: continue

        if not b.reachable:
            msg = f"Unused {b.type.replace('-', ' ')}: {b.name}"
            results.append({
                'file': filepath,
                'line': b.token.line,
                'column': b.token.col,
                'endColumn': b.token.end_col,
                'message': msg,
                'range_start': b.range_start,
                'range_end': b.range_end
            })

    if options.edit and results:
        new_code = list(code)
        # Sort results by range_start descending to avoid offset issues
        for res in sorted(results, key=lambda x: x['range_start'], reverse=True):
            if res['range_start'] < res['range_end']:
                # Also try to remove preceding whitespace and following newline
                start = res['range_start']
                end = res['range_end']

                # Check if it's the only thing on the line
                # This is a bit simplified
                while start > 0 and code[start-1] in ' \t': start -= 1
                if end < len(code) and code[end] == '\n': end += 1

                new_code[start:end] = []
        with open(filepath, 'w') as f:
            f.write("".join(new_code))

    return results

def main():
    parser = argparse.ArgumentParser(description='Find dead code in .nix files')
    parser.add_argument('file_paths', nargs='*', default=['.'])
    parser.add_argument('-l', '--no-lambda-arg', action='store_true')
    parser.add_argument('-L', '--no-lambda-pattern-names', action='store_true', dest='no_lambda_pattern')
    parser.add_argument('-_', '--no-underscore', action='store_true')
    parser.add_argument('-q', '--quiet', action='store_true')
    parser.add_argument('-e', '--edit', action='store_true')
    parser.add_argument('-h', '--hidden', action='store_true')
    parser.add_argument('-f', '--fail', action='store_true')
    parser.add_argument('-o', '--output-format', default='human-readable')
    parser.add_argument('--exclude', nargs='*', default=[])
    parser.add_argument('-V', '--version', action='store_true')

    args = parser.parse_args()
    if args.version:
        print("deadnix 1.3.1")
        return

    all_results = []
    files_to_process = []

    def add_files(path):
        if os.path.isfile(path):
            if path.endswith('.nix'): files_to_process.append(path)
        elif os.path.isdir(path):
            for root, dirs, files in os.walk(path):
                if not args.hidden:
                    dirs[:] = [d for d in dirs if not d.startswith('.')]
                for f in files:
                    if f.endswith('.nix'):
                        if not args.hidden and f.startswith('.'): continue
                        p = os.path.join(root, f)
                        files_to_process.append(p)

    for p in args.file_paths:
        add_files(p)

    # Filter excludes
    exclude_paths = [os.path.abspath(p) for p in args.exclude]
    files_to_process = [f for f in files_to_process if os.path.abspath(f) not in exclude_paths]
    # Also handle directory excludes
    files_to_process = [f for f in files_to_process if not any(os.path.abspath(f).startswith(e + os.sep) for e in exclude_paths)]

    for f in files_to_process:
        all_results.extend(run_on_file(f, args))

    if args.output_format == 'json':
        # Group by file
        grouped = {}
        for res in all_results:
            f = res['file']
            if f not in grouped: grouped[f] = {'file': f, 'results': []}
            grouped[f]['results'].append({
                'column': res['column'],
                'endColumn': res['endColumn'],
                'line': res['line'],
                'message': res['message']
            })
        for f in sorted(grouped.keys()):
            print(json.dumps(grouped[f]))
    else:
        if not args.quiet:
            for res in all_results:
                print(f"{YELLOW}Warning:{RESET} Unused declarations were found.")
                print(f"    {GRAY}╭─{RESET}{GRAY}[{RESET}{res['file']}:{res['line']}:{res['column']}{GRAY}]{RESET}")
                # Print code line
                with open(res['file'], 'r') as f:
                    lines = f.readlines()
                    line_content = lines[res['line']-1].rstrip('\n')
                    print(f" {GRAY}{res['line']} │{RESET} {LIGHT_GRAY}{line_content}{RESET}")
                    # Print pointer
                    padding = " " * (res['column'] - 1)
                    # This part is complex to match exactly, but let's try
                    pointer = " " * (res['column'] - 1) + RED + "╰" + "─" * (res['endColumn'] - res['column'] - 1) + " " + res['message'] + RESET
                    print(f" {DARK_GRAY}   │{RESET}     {pointer}")

    if args.fail and all_results:
        sys.exit(1)

if __name__ == '__main__':
    main()
