        name = t.value
        s = self.current_scope
        while s:
            if name in s.bindings:
                b = s.bindings[name]
                if is_root: b.reachable = True
                if hasattr(self, 'current_binding') and self.current_binding:
                    self.current_binding.refs.add(b)
