                if is_root: b.reachable = True
                if self.current_binding: self.current_binding.refs.add(b)
                return
            s = s.parent

def run_on_file(fp, opt):
    try:
        with open(fp, 'r') as f: code = f.read()
    except: return []
    res = []
    for b in Parser(Lexer(code).tokenize(), code, opt).parse():
        if b.skip or (b.name.startswith('_') and opt.no_underscore) or (b.type == 'lambda argument' and opt.no_lambda_arg) or (b.type == 'lambda pattern' and opt.no_lambda_pattern) or b.reachable: continue
        res.append({'file': fp, 'line': b.token.line, 'column': b.token.col, 'endColumn': b.token.end_col, 'message': f"Unused {b.type}: {b.name}", 'range_start': b.range_start, 'range_end': b.range_end})
    if opt.edit and res:
        nc = list(code)
        for r in sorted(res, key=lambda x: x['range_start'], reverse=True):
            if r['range_start'] < r['range_end']:
                s, e = r['range_start'], r['range_end']
                while s > 0 and code[s-1] in ' \t': s -= 1
                if e < len(code) and code[e] == '\n': e += 1
                nc[s:e] = []
        with open(fp, 'w') as f: f.write("".join(nc))
    return res

def main():
    p = argparse.ArgumentParser(add_help=False)
    p.add_argument('paths', nargs='*', default=['.'])
    p.add_argument('-l', '--no-lambda-arg', action='store_true')
    p.add_argument('-L', '--no-lambda-pattern-names', action='store_true', dest='no_lambda_pattern')
    p.add_argument('-_', '--no-underscore', action='store_true')
    p.add_argument('-q', '--quiet', action='store_true')
    p.add_argument('-e', '--edit', action='store_true')
    p.add_argument('-h', '--hidden', action='store_true')
    p.add_argument('-f', '--fail', action='store_true')
    p.add_argument('-o', '--output-format', default='human-readable')
    p.add_argument('--exclude', nargs='*', default=[])
    p.add_argument('-V', '--version', action='store_true')
    p.add_argument('--help', action='help')
    args = p.parse_args()
    if args.version: print("deadnix 1.3.1"); return
    fs = []
    def add(p):
        if os.path.isfile(p):
            if p.endswith('.nix'): fs.append(p)
        elif os.path.isdir(p):
            for r, ds, files in os.walk(p):
                if not args.hidden: ds[:] = [d for d in ds if not d.startswith('.')]
                for f in files:
                    if f.endswith('.nix') and (args.hidden or not f.startswith('.')): fs.append(os.path.join(r, f))
    for pt in args.paths: add(pt)
    ex = [os.path.abspath(x) for x in args.exclude]
    fs = [f for f in fs if os.path.abspath(f) not in ex and not any(os.path.abspath(f).startswith(e + os.sep) for e in ex)]
    rs = []
    for f in fs: rs.extend(run_on_file(f, args))
    if args.output_format == 'json':
        gs = {}
        for r in rs:
            if r['file'] not in gs: gs[r['file']] = {'file': r['file'], 'results': []}
            gs[r['file']]['results'].append({'column': r['column'], 'endColumn': r['endColumn'], 'line': r['line'], 'message': r['message']})
        for f in sorted(gs.keys()): print(json.dumps(gs[f]))
    elif not args.quiet:
        for r in rs:
            print(f"{YELLOW}Warning:{RESET} Unused declarations were found.")
            print(f"    {GRAY}╭─{RESET}{GRAY}[{RESET}{r['file']}:{r['line']}:{r['column']}{GRAY}]{RESET}")
            with open(r['file'], 'r') as f:
                lc = f.readlines()[r['line']-1].rstrip('\n')
                print(f" {GRAY}{r['line']: >2} │{RESET}{LIGHT_GRAY}{lc}{RESET}")
                # Simple pointer
                ptr = " " * (r['column'] - 1) + PURPLE + "╰" + "─" * (r['endColumn'] - r['column'] - 1) + " " + r['message'] + RESET
                print(f" {DARK_GRAY}   │{RESET}     {ptr}")
    if args.fail and rs: sys.exit(1)

if __name__ == '__main__': main()
