    p = argparse.ArgumentParser(add_help=False)
    p.add_argument('paths', nargs='*', default=['.'])
    p.add_argument('-l', '--no-lambda-arg', action='store_true')
    p.add_argument('-L', '--no-lambda-pattern-names', action='store_true', dest='no_lambda_pattern')
    p.add_argument('-_', '--no-underscore', action='store_true')
    p.add_argument('-q', '--quiet', action='store_true')
    p.add_argument('-e', '--edit', action='store_true')
    p.add_argument('-h', '--hidden', action='store_true')
    p.add_argument('-f', '--fail', action='store_true')
    p.add_argument('-o', '--output-format', default='human-readable')
    p.add_argument('--exclude', nargs='*', default=[])
    p.add_argument('-V', '--version', action='store_true')
    p.add_argument('--help', action='help')
    args = p.parse_args()
    if args.version: print("deadnix 1.3.1"); return
    fs = []
    def add(p):
        if os.path.isfile(p):
            if p.endswith('.nix'): fs.append(p)
        elif os.path.isdir(p):
            for r, ds, files in os.walk(p):
                if not args.hidden: ds[:] = [d for d in ds if not d.startswith('.')]
                for f in files:
                    if f.endswith('.nix') and (args.hidden or not f.startswith('.')): fs.append(os.path.join(r, f))
    for pt in args.paths: add(pt)
    ex = [os.path.abspath(x) for x in args.exclude]
    fs = sorted(list(set(f for f in fs if os.path.abspath(f) not in ex and not any(os.path.abspath(f).startswith(e + os.sep) for e in ex))))
    rs = []
    for f in fs: rs.extend(run(f, args))
    if args.output_format == 'json':
        gs = {}
        for r in rs:
            if r['file'] not in gs: gs[r['file']] = {'file': r['file'], 'results': []}
            gs[r['file']]['results'].append({'column': r['column'], 'endColumn': r['endColumn'], 'line': r['line'], 'message': r['message']})
        for f in sorted(gs.keys()): print(json.dumps(gs[f]))
    elif not args.quiet:
        for r in rs:
            print(f"{YELLOW}Warning:{RESET} Unused declarations were found.")
            print(f"    {GRAY}╭─{RESET}{GRAY}[{RESET}{r['file']}:{r['line']}:{r['column']}{GRAY}]{RESET}")
